package tv.plus.pro.home;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{
LinearLayout root;void page(String name){LinearLayout base=new LinearLayout(this);base.setOrientation(1);base.setPadding(28,24,28,24);base.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff090c23,0xff20104a,0xff10265e}));TextView h=new TextView(this);h.setText("▶ TV+   "+name);h.setTypeface(null,1);h.setTextColor(0xffffffff);h.setTextSize(30);h.setPadding(10,8,10,28);base.addView(h);ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);s.addView(root);base.addView(s);setContentView(base);}
void item(String name,Runnable click){TextView t=new TextView(this);t.setText(name);t.setTextSize(23);t.setTextColor(-1);t.setPadding(28,26,28,26);t.setFocusable(true);t.setGravity(android.view.Gravity.CENTER_VERTICAL);android.graphics.drawable.GradientDrawable normal=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff273866,0xff382465});normal.setCornerRadius(28);normal.setStroke(2,0xff6651b6);android.graphics.drawable.GradientDrawable focused=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xff5433c7,0xffae3bea});focused.setCornerRadius(28);t.setBackground(normal);t.setOnFocusChangeListener((v,f)->{t.setBackground(f?focused:normal);t.setScaleX(f?1.02f:1f);t.setScaleY(f?1.02f:1f);});t.setOnClickListener(v->click.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(4,8,4,8);root.addView(t,lp);}
void launch(String pkg){try{Intent i=getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(i==null)i=getPackageManager().getLaunchIntentForPackage(pkg);if(i==null){new AlertDialog.Builder(this).setTitle("Uygulama bulunamadı").setMessage(pkg+" kurulu değil veya Android TV tarafından görünmüyor.").setPositiveButton("Tamam",null).show();return;}startActivity(i);}catch(Exception e){new AlertDialog.Builder(this).setTitle("Uygulama açılamadı").setMessage(e.getClass().getSimpleName()+": "+e.getMessage()).setPositiveButton("Tamam",null).show();}}
void system(String action){try{startActivity(new Intent(action));}catch(Exception e){startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}}
@Override public void onCreate(Bundle b){super.onCreate(b);show();}
void show(){page("Ana Ekran");item("▶  TV+  |  Yeni nesil TV deneyimi",()->startActivity(new Intent(this,tv.plus.pro.gallery.MainActivity.class)));item("▦  Hızlı Uygulamalar",()->{page("Uygulamalar");Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LAUNCHER);android.content.pm.PackageManager pm=getPackageManager();for(android.content.pm.ResolveInfo r:pm.queryIntentActivities(q,0)){item(r.loadLabel(pm).toString(),()->launch(r.activityInfo.packageName));}});item("Uygulamalar",()->{page("Uygulamalar");android.content.pm.PackageManager pm=getPackageManager();java.util.HashSet<String> seen=new java.util.HashSet<>();for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER}){Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(category);for(android.content.pm.ResolveInfo r:pm.queryIntentActivities(q,0)){String id=r.activityInfo.packageName+"/"+r.activityInfo.name;if(!seen.add(id))continue;item(r.loadLabel(pm).toString(),()->{try{Intent i=new Intent();i.setClassName(r.activityInfo.packageName,r.activityInfo.name);startActivity(i);}catch(Exception e){new AlertDialog.Builder(this).setMessage("Uygulama açılamadı: "+e.getMessage()).setPositiveButton("Tamam",null).show();}});}}});item("TV+ Ayarlar",()->startActivity(new Intent(this,tv.plus.pro.settings.MainActivity.class)));item("TV+ Dosyalar",()->startActivity(new Intent(this,tv.plus.pro.folders.MainActivity.class)));item("TV+ Galeri",()->startActivity(new Intent(this,tv.plus.pro.gallery.MainActivity.class)));item("TV+ Ses",()->startActivity(new Intent(this,tv.plus.pro.volume.MainActivity.class)));}


}